// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(address target, uint256 amount, bytes calldata data) public {
        amount = bound(amount, 0, 0);
        address helper = address(new OwnerChanger(c));
        target = helper;
        vm.deal(c.owner(), amount);
        address originalOwner = c.owner();
        vm.prank(c.owner());
        c.sendMoney(target, amount, data);
        assertTrue(c.owner() == originalOwner);
    }
}

contract OwnerChanger {
    SimpleWallet public targetContract;
    constructor(SimpleWallet _c) { targetContract = _c; }
    fallback() external payable {
        assembly {
            sstore(0, 0xdead)
        }
    }
}
